def test_polars_df_with_null_values():
    """Polars DataFrame with null values should convert without error.
    Targets line 86: data.to_arrow() when columns contain nulls.
    """
    df = pl.DataFrame({"x": [1.0, None, 3.0], "y": [None, 2.0, None]})
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 3
    assert tbl.column("x").null_count == 1
    assert tbl.column("y").null_count == 2


def test_all_null_int_column():
    """An all-null Int64 column must survive coerce without error.
    Targets line 86: data.to_arrow() with every value null.
    """
    df = pl.DataFrame({"a": pl.Series([None, None, None], dtype=pl.Int64)})
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 3
    assert tbl.column("a").null_count == 3


def test_all_null_float_column():
    """An all-null Float64 column. Tests domain computation downstream.
    Targets line 86: all-null float column.
    """
    df = pl.DataFrame({"x": pl.Series([None, None], dtype=pl.Float64), "y": [1.0, 2.0]})
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 2
    assert tbl.column("x").null_count == 2


def test_polars_categorical_with_nulls():
    """Categorical column containing null values.
    Targets lines 79-80: cast path for pl.Categorical with nulls.
    """
    df = pl.DataFrame(
        {"cat": pl.Series(["a", None, "b"], dtype=pl.Categorical), "y": [1.0, 2.0, 3.0]}
    )
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 3
    assert tbl.column("cat").null_count == 1
    vals = tbl.column("cat").to_pylist()
    assert vals[1] is None


def test_polars_enum_with_nulls():
    """Enum column containing null values.
    Targets line 79: isinstance(dt, pl.Enum) branch with nulls.
    """
    df = pl.DataFrame(
        {
            "grade": pl.Series(["A", None, "C"], dtype=pl.Enum(["A", "B", "C"])),
            "y": [1.0, 2.0, 3.0],
        }
    )
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 3
    assert tbl.column("grade").null_count == 1


def test_nan_in_polars_float_column():
    """NaN values in polars float column. NaN is not null in polars; verify
    the Arrow table preserves them as NaN (not null).
    Targets line 86: data.to_arrow() with NaN values.
    """
    df = pl.DataFrame({"x": [float("nan"), 1.0, float("nan")]})
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 3
    vals = tbl.column("x").to_pylist()
    assert math.isnan(vals[0])
    assert math.isnan(vals[2])
    # NaN is NOT null in Arrow
    assert tbl.column("x").null_count == 0


def test_inf_in_polars_float_column():
    """Infinity values in polars float column.
    Targets line 86: data.to_arrow() with inf / -inf.
    """
    df = pl.DataFrame({"x": [float("inf"), float("-inf"), 0.0], "y": [1.0, 2.0, 3.0]})
    tbl = to_arrow_table(df)
    vals = tbl.column("x").to_pylist()
    assert vals[0] == float("inf")
    assert vals[1] == float("-inf")


