def test_polars_empty_dataframe():
    """Zero-row polars DataFrame.
    Targets line 86: data.to_arrow() with 0 rows.
    """
    df = pl.DataFrame(
        {"a": pl.Series([], dtype=pl.Int64), "b": pl.Series([], dtype=pl.Float64)}
    )
    tbl = to_arrow_table(df)
    assert isinstance(tbl, pa.Table)
    assert tbl.num_rows == 0
    assert "a" in tbl.column_names
    assert "b" in tbl.column_names


def test_polars_empty_dataframe_renders_valid_svg():
    """Zero-row polars DataFrame should produce valid SVG, not crash.
    Targets the full coerce -> render pipeline with empty data.
    """
    import ferrum as fr

    df = pl.DataFrame(
        {"x": pl.Series([], dtype=pl.Float64), "y": pl.Series([], dtype=pl.Float64)}
    )
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


