def test_very_large_floats():
    """Very large float values (1e300). Tests overflow handling.
    Targets line 86: to_arrow with extreme magnitudes.
    """
    df = pl.DataFrame({"x": [1e300, -1e300], "y": [1e-300, -1e-300]})
    tbl = to_arrow_table(df)
    assert tbl.num_rows == 2
    assert tbl.column("x").to_pylist() == [1e300, -1e300]


def test_very_large_integers():
    """i64 max boundary values.
    Targets line 86: to_arrow with extreme integers.
    """
    df = pl.DataFrame({"x": [2**63 - 1, -(2**63)], "y": [1.0, 2.0]})
    tbl = to_arrow_table(df)
    vals = tbl.column("x").to_pylist()
    assert vals[0] == 2**63 - 1
    assert vals[1] == -(2**63)


def test_extreme_values_render_no_nan_or_inf():
    """Extreme values should render without NaN or Infinity in SVG.
    Targets full pipeline with extreme data.
    """
    import ferrum as fr

    df = pl.DataFrame({"x": [1e300, 1e-300, -1e300], "y": [1.0, 2.0, 3.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_nan_inf_render_no_nan_in_svg():
    """Rendering data with NaN and Inf should not produce literal 'NaN' or
    'Infinity' strings in the SVG output.
    Targets the full coerce -> render pipeline.
    """
    import ferrum as fr

    df = pl.DataFrame(
        {"x": [1.0, float("nan"), 3.0, float("inf")], "y": [1.0, 2.0, float("-inf"), 4.0]}
    )
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg
    assert "Infinity" not in svg


def test_numpy_2d_float_inf_nan():
    """inf/nan values in a 2D numpy array should be representable.
    Targets lines 152-154.
    """
    arr = np.array([[float("inf"), float("-inf"), float("nan")]])
    tbl = to_arrow_table(arr)
    assert tbl.num_rows == 1
    val = tbl.column("col_0")[0].as_py()
    assert math.isinf(val) and val > 0


