def test_polars_multiple_cast_columns():
    """DataFrame with Date + Categorical + Duration columns simultaneously.
    Targets lines 74-84: multiple casts accumulated in the same pass.
    """
    from datetime import date

    df = pl.DataFrame(
        {
            "d": [date(2024, 1, 1), date(2024, 6, 15)],
            "cat": pl.Series(["a", "b"], dtype=pl.Categorical),
            "dur": pl.Series([1000, 2000], dtype=pl.Duration("ns")),
            "y": [1.0, 2.0],
        }
    )
    tbl = to_arrow_table(df)
    assert pa.types.is_timestamp(tbl.schema.field("d").type)
    assert pa.types.is_large_string(tbl.schema.field("cat").type) or pa.types.is_string(
        tbl.schema.field("cat").type
    )
    assert pa.types.is_int64(tbl.schema.field("dur").type)


