def test_pandas_series_with_zero_name():
    """Pandas Series with name=0 (integer zero, truthy check boundary).
    Targets line 99: `data.name if data.name is not None else 'value'`.
    Integer 0 is not None so should be used, but it's falsy.
    """
    pd = pytest.importorskip("pandas")
    s = pd.Series([1.0, 2.0], name=0)
    tbl = to_arrow_table(s)
    assert tbl.num_rows == 2
    # name=0 should become "0", NOT "value"
    assert "0" in tbl.column_names


