def test_all_null_column_renders_valid_svg():
    """All-null column used in x encoding should produce valid SVG.
    Targets full pipeline with degenerate all-null data.
    """
    import ferrum as fr

    df = pl.DataFrame(
        {"x": pl.Series([None, None, None], dtype=pl.Float64), "y": [1.0, 2.0, 3.0]}
    )
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


